INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass kollaborierende Roboter immer ohne Schutzzaun arbeiten können. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Risikoanalyse kann Schutzzaun erfordern"}, {"text": "Ja", "correct": false, "because": "Nicht immer sicher"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich, wenn ich einen kollaborierenden Roboter für ein IT-Projekt einsetze?', 3, '[{"text": "Sicherheitssensoren", "correct": true, "because": "Schützt Mitarbeiter"}, {"text": "Maximale Geschwindigkeit", "correct": false, "because": "Sicherheit hat Vorrang"}, {"text": "Buntes Design", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften machen kollaborierende Roboter nützlich?', 5, '[{"text": "Flexibilität", "correct": true, "because": "Anpassung an Aufgaben"}, {"text": "Sicherheitssensoren", "correct": true, "because": "Schützt bei Kontakt"}, {"text": "Hohe Kosten", "correct": false, "because": "Nicht entscheidend"}, {"text": "Komplexe Programmierung", "correct": false, "because": "Sollte einfach sein"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Cobots arbeiten direkt mit Menschen zusammen. b) Sie ersetzen immer menschliche Arbeit.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Unterstützen, nicht ersetzen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich einen kollaborierenden Roboter für Serverwartung einsetze?', 4, '[{"text": "Sicherheitsnormen", "correct": false, "because": "Müssen eingehalten werden"}, {"text": "Programmierbarkeit", "correct": false, "because": "Wichtig für Einsatz"}, {"text": "Roboterfarbe", "correct": true, "because": "Kein funktionaler Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob kollaborierende Roboter immer selbstständig arbeiten?', 2, '[{"text": "Nein", "correct": true, "because": "Brauchen oft menschliche Steuerung"}, {"text": "Ja", "correct": false, "because": "Nicht immer autonom"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit einem kollaborierenden Roboter in der Produktion?', 3, '[{"text": "Mitarbeiterentlastung", "correct": true, "because": "Übernimmt monotone Aufgaben"}, {"text": "Maximale Geschwindigkeit", "correct": false, "because": "Sicherheit wichtiger"}, {"text": "Weniger Teamarbeit", "correct": false, "because": "Fördert Zusammenarbeit"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren machen kollaborierende Roboter effektiv?', 5, '[{"text": "Einfache Bedienung", "correct": true, "because": "Fördert Nutzung"}, {"text": "Kraftsensoren", "correct": true, "because": "Sichert Sicherheit"}, {"text": "Hohe Anschaffungskosten", "correct": false, "because": "Nicht entscheidend"}, {"text": "Komplexe Installation", "correct": false, "because": "Sollte simpel sein"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Kollaborierende Roboter sind leicht programmierbar. b) Sie brauchen immer einen Schutzzaun. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Schutzzaun oft nicht nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für den Einsatz eines kollaborierenden Roboters?', 4, '[{"text": "Sicherheitsprüfung", "correct": false, "because": "Notwendig für Betrieb"}, {"text": "Flexibles Design", "correct": false, "because": "Wichtig für Anpassung"}, {"text": "Luxusausstattung", "correct": true, "because": "Kein funktionaler Nutzen"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind kollaborierende Roboter nur für große Firmen geeignet?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für KMU nützlich"}, {"text": "Ja", "correct": false, "because": "Flexibel einsetzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein kollaborierender Roboter in der IT?', 4, '[{"text": "Ergonomische Unterstützung", "correct": true, "because": "Entlastet bei Aufgaben"}, {"text": "Teamzusammenarbeit", "correct": true, "because": "Fördert Kooperation"}, {"text": "Hohe Kosten", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass kollaborierende Roboter immer gefährlich sind. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Sicherheitsmechanismen schützen"}, {"text": "Ja", "correct": false, "because": "Mit Sensoren gesichert"}]'),
('00000000-0000-0000-0000-000000000000', 'Was wähle ich, um einen kollaborierenden Roboter für Montageaufgaben einzusetzen?', 3, '[{"text": "Einfache Programmierung", "correct": true, "because": "Spart Zeit"}, {"text": "Maximale Traglast", "correct": false, "because": "Sicherheit wichtiger"}, {"text": "Bunte Optik", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Cobots nutzen Sensoren für Sicherheit. b) Sie sind immer langsamer als Industrieroboter.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Geschwindigkeit variiert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte berücksichtige ich bei der Nutzung eines kollaborierenden Roboters?', 5, '[{"text": "Mensch-Roboter-Interaktion", "correct": true, "because": "Kern der Kollaboration"}, {"text": "Sicherheitsstandards", "correct": true, "because": "Schützt Team"}, {"text": "Hohe Bandbreite", "correct": false, "because": "Kein direkter Faktor"}, {"text": "Luxuriöse Optik", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist unwichtig, wenn ich einen kollaborierenden Roboter für ein IT-Projekt einsetze?', 3, '[{"text": "Bedienbarkeit", "correct": false, "because": "Fördert Nutzung"}, {"text": "Sicherheit", "correct": false, "because": "Schützt Mitarbeiter"}, {"text": "Markenimage", "correct": true, "because": "Kein funktionaler Nutzen"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ersetzen kollaborierende Roboter die IT-Mitarbeiter?', 3, '[{"text": "Nein", "correct": true, "because": "Unterstützen, nicht ersetzen"}, {"text": "Ja", "correct": false, "because": "Ziel ist Zusammenarbeit"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob kollaborierende Roboter für einfache Aufgaben geeignet sind?', 2, '[{"text": "Ja", "correct": true, "because": "Flexibel einsetzbar"}, {"text": "Nein", "correct": false, "because": "Auch für Simples nützlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Feature ist entscheidend für kollaborierende Roboter?', 4, '[{"text": "Kraftsensoren", "correct": true, "because": "Sichert Sicherheit bei Kontakt"}, {"text": "Hohe Geschwindigkeit", "correct": false, "because": "Sicherheit wichtiger"}, {"text": "Bunte Lichter", "correct": false, "because": "Irrelevant"}]');
